from pathlib import Path
import base64, hashlib, json

ROOT = Path(__file__).resolve().parent
OUT = ROOT / "static" / "realism.html"
PREVIEW_FILES = {
    "realcomic": "realism-realcomic.webp", "realism_krea2": "realism-krea2.webp",
    "realism_2511": "realism-2511.webp", "realism_multisample": "realism-multisample.webp",
    "realism_qwen_zi": "realism-qwen-zi.webp", "realism_zi_flowmatch": "realism-zi-flowmatch.webp",
}
def preview_url(filename):
    path = ROOT / "static" / "previews" / filename
    return "/static/previews/" + filename + "?v=" + hashlib.sha256(path.read_bytes()).hexdigest()[:12]
def preview_data_uri(filename):
    path = ROOT / "static" / "previews" / filename
    return "data:image/webp;base64," + base64.b64encode(path.read_bytes()).decode("ascii")
WORKFLOW_PREVIEWS = {key: preview_url(filename) for key, filename in PREVIEW_FILES.items()}
WORKFLOW_PREVIEW_THUMBS = {key: preview_data_uri(filename.replace(".webp", ".thumb.webp")) for key, filename in PREVIEW_FILES.items()}

